INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES ("", "", 111031, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", 13020023, "", 10, 11, 302, "");
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES ("", "", 0, "", "", 13020024, "", "", 91, 302, "");
